from pathlib import Path

def pipeline_tree(root):
    root=Path(root)
    h=hashlib.sha256(); pending=[root]; entries=[]
    while pending:
      d=pending.pop()
      for child in os.scandir(d):
        p=Path(child.path); mode=child.stat(follow_symlinks=False).st_mode; rel=p.relative_to(root).as_posix()
        if stat.S_ISDIR(mode): entries.append((rel,'directory',p)); pending.append(p)
        elif stat.S_ISREG(mode): entries.append((rel,'file',p))
